const REVIEWS=[{"name": "Greg Brouse", "when": "2026", "src": "google", "text": "We bought two sheds from Classic Shed Builders and are very pleased with the everything about them. Good quality, easy order, updates during the one custom build, great timing on delivery…"}, {"name": "Ashley Wagner", "when": "2025", "src": "google", "text": "We have bought two sheds from Classic Shed Builders. We are pleased with the quality of both sheds. Highly recommend!"}, {"name": "Jay Gill", "when": "2024", "src": "google", "text": "They made the wife happy and so when the wife is happy... life is happy! Great quality and beautiful buildings."}, {"name": "Kati Gill", "when": "2024", "src": "google", "text": "These sheds are absolutely stunning and are of the highest quality!"}, {"name": "Terry Kelley", "when": "Apr 2026", "src": "facebook", "text": "If you are looking for a quality shed, your first stop should be to see Matt in Beaver Springs, PA. The shed is fantastic and Matt did a wonderful job! I had him put the pad in and he delivered the shed in the same day! He is a very good person to deal with! Thank you Matt for a wonderful job!"}, {"name": "Chris Buckholtz", "when": "Jan 2026", "src": "facebook", "text": "Recently purchased a shed… Matt and his team were great to work with from time of purchase, to prep work and final placement. If you're looking for a shed definitely give them a call"}, {"name": "Dennis Sunderland", "when": "Dec 2025", "src": "facebook", "text": "…the only place that I would recommend getting a unit from. Matt helped me design my lean to and it turned out perfect, he stayed in contact with me and gave me updates and everything went as planned, it was delivered on the day and time he said that it would. They even came the day I received my unit to check on the placement and the overall unit."}, {"name": "Alice Reitenbach", "when": "Dec 2025", "src": "facebook", "text": "My husband and I recently purchased a pavilion/shed… Matt was great to work with, the price was more than competitive and the structure turned out great. The delivery driver did a nice job placing it too."}, {"name": "Elizabeth Barner", "when": "Jun 2025", "src": "facebook", "text": "Great experience… They helped us find the perfect shed to fit all of our needs."}, {"name": "Phil Kuntz", "when": "May 2025", "src": "facebook", "text": "I recently had a wood shed delivered to my property. The location where we wanted to place the shed was challenging. Matt was a true professional and was able to get the shed where we wanted it. We searched for a shed like this for quite some time. It is a quality shed and It was fairly priced."}, {"name": "Matthew Minier", "when": "Apr 2025", "src": "facebook", "text": "Matt and Rob are extremely knowledgeable and friendly. If you value your dollar, give them a visit. They won't disappoint with their value, build quality, and service! From helping to pick the right shed for you, the purchase process, all the way to delivery, they are top notch."}, {"name": "Newman, Engineer", "when": "", "src": "testimonial", "text": "We have purchased a total of five sheds to date. I would only purchase a Classic. I have researched a lot of sheds and beyond all others Classic has the best quality for the money."}];
