const $=id=>document.getElementById(id);
/* pages: in the one-file preview, show one page at a time (#/page or #/page/section) */
(()=>{const pages=[...document.querySelectorAll('.page')];if(pages.length<2)return;
 function show(){const m=location.hash.match(/^#\/([\w-]*)\/?([\w-]*)$/);let p='home',a='';
  if(m){p=m[1]||'home';a=m[2]}else if(location.hash.length>1){a=location.hash.slice(1)}
  if(!pages.some(x=>x.dataset.page===p))p='home';
  pages.forEach(x=>{x.hidden=x.dataset.page!==p});
  const cur=pages.find(x=>x.dataset.page===p);document.title=cur.dataset.title;
  document.dispatchEvent(new Event('pageshown'));
  const el=a&&document.getElementById(a);if(el)el.scrollIntoView();else scrollTo(0,0);}
 addEventListener('hashchange',show);show();})();
/* October special: hide after October 31, 2026 */
if(Date.now()>=Date.parse('2026-11-01T00:00:00-04:00'))document.querySelectorAll('.offer').forEach(o=>o.remove());
/* menu */
(()=>{const b=$('burger'),d=$('drawer');
 b.addEventListener('click',()=>{d.hidden=!d.hidden;b.setAttribute('aria-expanded',String(!d.hidden))});
 d.addEventListener('click',e=>{if(e.target.closest('a')){d.hidden=true;b.setAttribute('aria-expanded','false')}});})();
/* back to top */
(()=>{const t=$('totop');addEventListener('scroll',()=>{t.hidden=scrollY<700},{passive:true});t.onclick=()=>scrollTo({top:0,behavior:'smooth'});})();
/* photo carousel */
(()=>{const c=$('car');if(!c)return;const s=[...c.querySelectorAll('.cslide')];const dots=$('dots');let i=0,t;
 s.forEach((_,k)=>{const b=document.createElement('button');b.type='button';b.setAttribute('aria-label','Show photo '+(k+1));b.onclick=()=>{go(k);auto()};dots.appendChild(b)});
 const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function go(n){i=(n+s.length)%s.length;s.forEach((x,k)=>x.classList.toggle('on',k===i));[...dots.children].forEach((x,k)=>x.classList.toggle('on',k===i));s[i].querySelector('img').loading='eager';}
 function auto(){clearInterval(t);if(!reduce)t=setInterval(()=>{if(!document.hidden)go(i+1)},5000)}
 c.querySelector('.cnext').onclick=()=>{go(i+1);auto()};c.querySelector('.cprev').onclick=()=>{go(i-1);auto()};
 let sx=null;c.addEventListener('touchstart',e=>{sx=e.touches[0].clientX},{passive:true});c.addEventListener('touchend',e=>{if(sx===null)return;const dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>40){go(i+(dx<0?1:-1));auto()}sx=null},{passive:true});
 go(0);auto();})();
/* review carousel, one at a time */
(()=>{const card=$('rvcard'),cnt=$('rvcount');if(!card)return;let i=0,t;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function render(){const r=REVIEWS[i];
  const top=r.src==='google'?`<div class="stars" aria-label="5 out of 5 stars">${ICON.star.repeat(5)}</div><span class="when">${r.when}</span>`
   :r.src==='facebook'?`<span class="rec">${ICON.rec} Recommends</span><span class="when">${r.when}</span>`:`<span class="rec">Customer testimonial</span><span class="when">${r.when}</span>`;
  const who=`<span class="who">${r.name}${r.src==='google'?' '+ICON.check:''}</span>`;
  const src=r.src==='google'?`<span class="src" aria-label="Google review">${ICON.g}</span>`:r.src==='facebook'?`<span class="src" aria-label="Facebook recommendation">${ICON.fb}</span>`:'<span></span>';
  card.innerHTML=top+`<p class="txt">${r.text}</p>`+who+src;cnt.textContent=(i+1)+' of '+REVIEWS.length+' reviews';}
 function go(n){i=(n+REVIEWS.length)%REVIEWS.length;render()}
 function auto(){clearInterval(t);if(!reduce)t=setInterval(()=>{if(!document.hidden)go(i+1)},6000)}
 $('rvn').onclick=()=>{go(i+1);auto()};$('rvp').onclick=()=>{go(i-1);auto()};
 let sx=null;card.addEventListener('touchstart',e=>{sx=e.touches[0].clientX},{passive:true});card.addEventListener('touchend',e=>{if(sx===null)return;const dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>40){go(i+(dx<0?1:-1));auto()}sx=null},{passive:true});
 render();auto();})();
/* cards: learn more */
document.querySelectorAll('[data-more]').forEach(b=>b.addEventListener('click',()=>{const c=b.closest('.card');const o=c.classList.toggle('open');b.textContent=o?'Show Less':'Learn More'}));
/* "Get a Quote" on a card pre-selects the building on the contact page */
document.querySelectorAll('[data-pick]').forEach(a=>a.addEventListener('click',()=>{try{sessionStorage.setItem('pick',a.dataset.pick)}catch(e){}}));
function applyPick(){const sel=$('q-type');if(!sel)return;try{const v=sessionStorage.getItem('pick');if(v){sel.value=v;sessionStorage.removeItem('pick')}}catch(e){}}
applyPick();document.addEventListener('pageshown',applyPick);
/* rent to own price table: 60-month amounts from the price list; 48/36/24 use the list's divisors (LP SmartSide and custom vinyl structures) */
(()=>{const sel=$('rto-style');if(!sel)return;
 const MAX=25000,TERMS=['LP SmartSide Structures','LP SmartSide Garages','Custom Vinyl Structures','Vinyl Garages'],DIV=[[48,24],[36,21.6],[24,16.9]];
 const n=s=>+s.replace(/[$,]/g,''),money=x=>'$'+x.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}),ft=s=>s.replace(' x ',"' x ")+"'";
 const groups={};PRICES.forEach((p,k)=>{(groups[p[0]]=groups[p[0]]||[]).push(k)});
 sel.innerHTML=Object.entries(groups).map(([g,ks])=>`<optgroup label="${g}">`+ks.map(k=>`<option value="${k}">${PRICES[k][1]}</option>`).join('')+'</optgroup>').join('');
 function draw(){const p=PRICES[+sel.value],rows=p[2],terms=TERMS.includes(p[0]);
  document.querySelector('#prices table.rto thead tr').innerHTML='<th scope="col">Size</th><th scope="col">Cash price</th><th scope="col">Rent to own, 60 months</th>'+(terms?DIV.map(d=>`<th scope="col">${d[0]} months</th>`).join(''):'');
  $('rto-body').innerHTML=rows.map(r=>{const c=n(r[1]),span=terms?4:1;
   const rto=!r[2]?`<td colspan="${span}">Call for financing</td>`:c>MAX?`<td colspan="${span}">Over the $25,000 rent-to-own limit</td>`:`<td class="m">${r[2]}/mo</td>`+(terms?DIV.map(d=>`<td>${money(Math.round(c/d[1]*100)/100)}/mo</td>`).join(''):'');
   return `<tr><td>${ft(r[0])}${r[2]?'':' †'}</td><td>${r[1]}</td>`+rto+'</tr>'}).join('');
  const r=rows.find(x=>x[2]);$('rto-ex').innerHTML=`Example: the <b>${ft(r[0])} ${p[1]}</b> is <b>${r[1]}</b> cash, or <b>${r[2]} a month</b> on 60-month rent-to-own`+(terms?` (${DIV.map(d=>money(Math.round(n(r[1])/d[1]*100)/100)+' for '+d[0]).join(', ')} months).`:'.');}
 sel.addEventListener('change',draw);draw();})();
/* quote form: sends to the form service when data-endpoint is set, otherwise prepares the text */
(()=>{const f=$('qform');if(!f)return;const v=id=>$(id).value.trim();
 f.addEventListener('submit',async e=>{e.preventDefault();
  if(f.dataset.endpoint){const b=f.querySelector('button[type=submit]');b.disabled=true;b.textContent='Sending…';
   try{const r=await fetch(f.dataset.endpoint,{method:'POST',body:new FormData(f),headers:{Accept:'application/json'}});if(r.ok){location.href=f.dataset.thanks;return}}catch(err){}
   b.disabled=false;b.textContent='Submit Form';}
  const t=`Quote request – Classic Shed Builders LLC\nName: ${v('q-first')} ${v('q-last')}\nPhone: ${v('q-phone')}\nEmail: ${v('q-email')}\nZip: ${v('q-zip')}\nBuilding: ${v('q-type')}\n\n${v('q-msg')}`;
  $('qtext').textContent=t;$('qout').classList.add('show');});
 $('qcopy').addEventListener('click',e=>{const b=e.currentTarget,t=$('qtext');
  navigator.clipboard.writeText(t.textContent).then(()=>{b.textContent='Copied'},()=>{const r=document.createRange();r.selectNodeContents(t);const s=getSelection();s.removeAllRanges();s.addRange(r);b.textContent='Text selected, copy it'});});})();
/* price lists page: styles with features and every size, options, specifications */
(()=>{const box=document.querySelectorAll('.plstyles');if(!box.length)return;
 const esc=t=>t.replace(/&/g,'&amp;').replace(/</g,'&lt;'),ft=s=>s.replace(' x ',"' x ")+"'";
 box.forEach(b=>{b.innerHTML=PRICES.filter(p=>p[0]===b.dataset.cat).map(p=>{const name=p[1],rows=p[2],first=rows.find(r=>r[2])||rows[0];
  const f=(PLDATA.features[name]||[]).map(x=>`<li>${esc(x)}</li>`).join(''),w=PLDATA.walls[name]||'';
  const tr=rows.map(r=>`<tr><td>${ft(r[0])}${r[2]?'':' †'}</td><td>${r[1]}</td><td class="m">${r[2]?r[2]+'/mo':'Call'}</td></tr>`).join('');
  return `<details class="plstyle"><summary><span><b>${esc(name)}</b>${w?`<small>${esc(w)}</small>`:''}</span><span class="from">from <b>${first[1]}</b><em>or ${first[2]}/mo</em></span></summary><div class="plbody">${f?`<div><h4>Included in base model</h4><ul class="ticks">${f}</ul></div>`:''}<div class="tablewrap"><table class="rto"><thead><tr><th scope="col">Size</th><th scope="col">Cash price</th><th scope="col">Rent to own, 60 months</th></tr></thead><tbody>${tr}</tbody></table></div></div></details>`}).join('')});
 document.querySelectorAll('.plopts').forEach(o=>{o.innerHTML=PLDATA.options[o.dataset.line].map(([g,items])=>`<details class="plgroup"><summary>${esc(g)}</summary><table class="plopt"><tbody>${items.map(([a,c])=>`<tr><td>${esc(a)}</td><td>${esc(c)}</td></tr>`).join('')}</tbody></table></details>`).join('')});
 document.querySelectorAll('.plspecs').forEach(d=>{d.innerHTML=PLDATA.specs[d.dataset.line].map(([a,c])=>`<div><dt>${esc(a)}</dt><dd>${esc(c)}</dd></div>`).join('')});})();
